def max_subarray_product(nums):
    max_product = 0
    max_product_end = 0
    for i in range(len(nums)):
        if nums[i] > 0:
            max_product_end = max(max_product_end, nums[i])
            max_product = max(max_product, max_product_end * nums[i])
        else:
            max_product_end = 0
    return max_product

